import{_ as e,o as r,c as t,O as o}from"./chunks/framework.e0b066fe.js";const d=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"practice/youzan2.md","filePath":"practice/youzan2.md","lastUpdated":null}'),i={name:"practice/youzan2.md"};function h(n,a,c,l,s,p){return r(),t("div",null,a[0]||(a[0]=[o('<h2 id="平时有用ai编辑器吗" tabindex="-1">平时有用AI编辑器吗 <a class="header-anchor" href="#平时有用ai编辑器吗" aria-label="Permalink to &quot;平时有用AI编辑器吗&quot;">​</a></h2><p>现在很多开发者会使用 AI 编辑器（如 GitHub Copilot、Cursor、ChatGPT 插件等）来辅助编程，提高效率、自动补全代码、生成注释等。</p><h2 id="遍历数组方法" tabindex="-1">遍历数组方法 <a class="header-anchor" href="#遍历数组方法" aria-label="Permalink to &quot;遍历数组方法&quot;">​</a></h2><p>常见的数组遍历方法有：for、forEach、map、filter、reduce、some、every、for...of 等。</p><h2 id="map和foreach的区别" tabindex="-1">map和forEach的区别 <a class="header-anchor" href="#map和foreach的区别" aria-label="Permalink to &quot;map和forEach的区别&quot;">​</a></h2><p>map 会返回一个新数组，数组元素是回调函数的返回值；forEach 不返回新数组，只是对每个元素执行回调函数。</p><h2 id="遍历对象方法" tabindex="-1">遍历对象方法 <a class="header-anchor" href="#遍历对象方法" aria-label="Permalink to &quot;遍历对象方法&quot;">​</a></h2><p>常见方法有：for...in、Object.keys(obj)、Object.values(obj)、Object.entries(obj)。</p><h2 id="for-in和object-keys区别" tabindex="-1">for in和Object.keys区别 <a class="header-anchor" href="#for-in和object-keys区别" aria-label="Permalink to &quot;for in和Object.keys区别&quot;">​</a></h2><p>for...in 会遍历对象自身和原型链上的可枚举属性；Object.keys 只返回对象自身的可枚举属性（不包括原型链）。</p><h2 id="判断类型的方法" tabindex="-1">判断类型的方法 <a class="header-anchor" href="#判断类型的方法" aria-label="Permalink to &quot;判断类型的方法&quot;">​</a></h2><p>常见方法有：typeof、instanceof、Object.prototype.toString.call()、Array.isArray()。</p><h2 id="typeof缺陷是什么" tabindex="-1">typeof缺陷是什么 <a class="header-anchor" href="#typeof缺陷是什么" aria-label="Permalink to &quot;typeof缺陷是什么&quot;">​</a></h2><p>typeof 不能准确判断 null（返回 object），也不能区分数组和对象（数组返回 object）。</p><h2 id="数组怎么判断" tabindex="-1">数组怎么判断 <a class="header-anchor" href="#数组怎么判断" aria-label="Permalink to &quot;数组怎么判断&quot;">​</a></h2><p>可以用 Array.isArray(arr) 或 Object.prototype.toString.call(arr) === &#39;[object Array]&#39;。</p><h2 id="nan怎么判断" tabindex="-1">NaN怎么判断 <a class="header-anchor" href="#nan怎么判断" aria-label="Permalink to &quot;NaN怎么判断&quot;">​</a></h2><p>用 Number.isNaN(value) 或 isNaN(value)（注意 isNaN 会有类型转换，推荐用 Number.isNaN）。</p><h2 id="typeof-数组返回什么" tabindex="-1">typeof 数组返回什么 <a class="header-anchor" href="#typeof-数组返回什么" aria-label="Permalink to &quot;typeof 数组返回什么&quot;">​</a></h2><p>typeof 数组返回 &quot;object&quot;。</p><h2 id="react类组件和函数组件区别" tabindex="-1">react类组件和函数组件区别 <a class="header-anchor" href="#react类组件和函数组件区别" aria-label="Permalink to &quot;react类组件和函数组件区别&quot;">​</a></h2><p>类组件用 class 声明，有生命周期和 this；函数组件用 function 声明，不能直接使用生命周期，但可以用 Hook。</p><h2 id="react-hook为什么不能放条件里面" tabindex="-1">react hook为什么不能放条件里面 <a class="header-anchor" href="#react-hook为什么不能放条件里面" aria-label="Permalink to &quot;react hook为什么不能放条件里面&quot;">​</a></h2><p>因为 Hook 的调用顺序必须一致，放在条件语句里会导致顺序不一致，React 无法正确管理状态。</p><h2 id="箭头函数普通函数区别" tabindex="-1">箭头函数普通函数区别 <a class="header-anchor" href="#箭头函数普通函数区别" aria-label="Permalink to &quot;箭头函数普通函数区别&quot;">​</a></h2><p>箭头函数没有自己的 this、arguments、super、new.target，this 指向外层作用域；普通函数有自己的 this，调用方式不同 this 指向不同。</p><h2 id="vue-响应式原理" tabindex="-1">vue 响应式原理 <a class="header-anchor" href="#vue-响应式原理" aria-label="Permalink to &quot;vue 响应式原理&quot;">​</a></h2><p>Vue 通过 Object.defineProperty（Vue2）或 Proxy（Vue3）劫持数据，实现数据变化自动更新视图。</p><h2 id="cursor一直以来更换的模型-用什么模型比较多" tabindex="-1">cursor一直以来更换的模型，用什么模型比较多 <a class="header-anchor" href="#cursor一直以来更换的模型-用什么模型比较多" aria-label="Permalink to &quot;cursor一直以来更换的模型，用什么模型比较多&quot;">​</a></h2><p>Cursor 编辑器常用的 AI 模型有 OpenAI 的 GPT-3.5、GPT-4，Claude、Gemini 等，实际使用以 OpenAI 的 GPT 系列为主。</p>',30)]))}const f=e(i,[["render",h]]);export{d as __pageData,f as default};
